class FixedWindow:
    def __init__(self, limit):
        self.limit, self.bucket, self.count = limit, None, 0
    def allow(self, t):
        b = t // 60
        if b != self.bucket:
            self.bucket, self.count = b, 0
        if self.count >= self.limit:
            return False
        self.count += 1
        return True

class SlidingWindow:
    def __init__(self, limit):
        self.limit, self.hits = limit, []
    def allow(self, t):
        self.hits = [h for h in self.hits if t - h < 60]
        if len(self.hits) >= self.limit:
            return False
        self.hits.append(t)
        return True

for name, cls in (("fixed", FixedWindow), ("sliding", SlidingWindow)):
    lim = cls(100)
    for _ in range(100):
        lim.allow(59)
    burst = sum(lim.allow(60) for _ in range(100))
    print(name, "window: extra allowed at t=60:", burst)

