class Store:
    def __init__(self):
        self.replicas = {"doc-9": ["node-a", "node-b"]}
    def delete(self, doc, node):
        copies = self.replicas[doc]
        if len(copies) <= 1:
            return "refused:last-copy"
        copies.remove(node)
        return "deleted"

s = Store()
print("delete from node-a (2 copies):", s.delete("doc-9", "node-a"))
print("delete from node-b (1 copy left):", s.delete("doc-9", "node-b"))
print("doc-9 still exists on:", s.replicas["doc-9"])

def mask(number):
    return "**** **** **** " + number[-4:]

def log_event(kind, number):
    return "[%s] card %s" % (kind, mask(number))

card = "4242424242424242"
lines = []
lines.append(log_event("charge", card))
try:
    raise ValueError("charge failed for card " + mask(card))
except ValueError as e:
    lines.append(log_event("error", card) + " | " + str(e))
for line in lines:
    print(line)
print("full number present in any line:", any(card in line for line in lines))

def sync(records, server):
    applied, failed = [], []
    for r in records:
        if server(r):
            applied.append(r)
        else:
            failed.append(r)
    return applied, failed   # no automatic retry: failures returned for decision

def flaky(r):
    return r != "rec-3"

applied, failed = sync(["rec-1", "rec-2", "rec-3", "rec-4"], flaky)
print("applied:", applied)
print("failed (returned, not retried):", failed)
print("server saw each record exactly once:", len(applied) + len(failed) == 4)

# Spec clause: "Loyalty points: 1 point per full dollar spent.
# Worked examples from the spec: $9.99 -> 9 points; $10.00 -> 10 points;
# $0.50 -> 0 points."
def points(spent_cents):
    return spent_cents // 100

examples = [(999, 9), (1000, 10), (50, 0)]
for cents, want in examples:
    got = points(cents)
    print("spend", cents, "cents -> points", got, "| spec example:", want,
          "|", "PASS" if got == want else "FAIL")
